"""Reader-oriented result and handoff, without build narration."""
from dental_release.paths import expand as _release_expand
import json, datetime
from pathlib import Path
from contact import P, sha, write, state

def run():
    import csv
    with (P / 'raw/TOOTH_PAIR_MAP.csv').open() as f:
        exported = list(csv.DictReader(f))
    tight = [p for p in exported if p['enclosure_round'] == 'R4']
    maximum_width = max((float(p['minimum_enclosure_upper_mm']) - float(p['minimum_enclosure_lower_mm']) for p in tight))
    assert len(exported) == 38280 and len(tight) == 440 and (maximum_width <= 0.005 + 1e-09)
    write(P / 'raw/EXPORT_CHECK.json', dict(passed=True, rows=len(exported), refined_R4_rows=len(tight), maximum_refined_width_mm=maximum_width, remaining_rows_model='R3 conservative bound'))
    r = json.load(open(P / 'results.json'))
    rd = r['rounds']
    r5 = rd['R5']
    r6 = rd['R6']
    t = r['toothwise_crossbite']
    cost = r['costs']
    field = rd['R2']['fields']
    old = r5['test_report_disagreement_original']
    new = r5['test_report_disagreement_corrected']
    allnew = r5['all_cohort_disagreement_corrected']
    text = _release_expand("# Per tooth gap map against the clinicer's bite description\n\nRun `./run_all.sh` from this directory. [Figure](figures/contact_report_demo.png), [gap certificate](figures/certificate_width.png), [CSV ](raw/TOOTH_PAIR_MAP.csv). An existing case can be read with `python3 code/demo_case.py --case @DENTAL_CASE_ID@`; custom STL pairs with X11 labels are supported via `--upper --lower --segmentation`.\n\nThe idea: keep dental identity, opposite surface and non-contact geometry in the same registered scanning pairs. Continuous gaps get source triangles and mathematical intervals; projected proximity patches get area and position. The opposite point candidates are retained when no contact is made. The linguistics' existing text is compared as a separate observation, with negation and anatomical region preserved.\n\nReference : [Bite2Text author dataset](https://ditto.ing.unimore.it/bite2text/), local `Bite2Text.zip::*/reports_ios_en/*.txt` , 1 494 readable structured reports. Source member and SHA256 follow each comparison. The text measures categories and named crucifix teeth, **not gap, area or point coordinates**. Mathematical gapfacit is affee minimum over projected triangle intersection, with exact rational witnesses and independent full tooth parsing controls. [Eberly's primary derivation](https://www.geometrictools.com/Documentation/MethodOfSeparatingAxes.pdf), § 2 – 3 , indicates linear projection minimum over convex polygons corners; here this applies to our affinity gap. It is a derived application for rounded mesh, no empirical contact validation. EXTERNAL_REFERENTS.json is a metadata appdix; no gates was changed.\n\n| Executable capability | Actually result | Giltighet |\n|---|---:|---|\n| Tandvisa kartor | 993 pairs, 38 280 projected overlapping tooth pairs | Calculated FDI and unchanged source pose |\n| Konservativa minimigapintyg | 38 280/38 280 giltiga intervall | Medianbredd0,266mm ; usability gate FAIL |\n| Precisely refined certificates | 440 tooth pairs, 12 default cases; max width 0,004998 mm | PASS ; 981 second case retains wider certificates |\n| Rasterarea, 0,2→0,1mm | All 12 actual refinement gates PASS | Projection and proximity band 0,10 mm; no physical area |\n| Negationsfel i klinikerfacit | 121 positiva korsbettsetiketter korrigerade | Original and exact source statements preserved |\n| Report conflict for cross-bite, test | 30/72→7/72 (41,7%→9,7%) | Corrected category of text, not identified inter-assess noise |\n| Regional report finding | ") + str(r6['mixed_anterior_positive_lateral_negative_reports']) + ' Anterior-positive/lateral-negative reports | Different regions can be described simultaneously without contradiction |\n| Felkontroller | 125 / 125 explicitly negative lateral statements rejects positive injection | Physical dental diagnosis still UNKNOWN |\n\n'
    text += '| Comparison with first readable test report | Exact match | Balanced match | X7 balanced hit | Multiple reports disagree |\n|---|---:|---:|---:|---:|\n'
    labels = {'overbite': 'Overbite, R2', 'overjet': 'Overjet, R2', 'molar_right': 'M1 /Angle right, R2', 'molar_left': 'M1 /Angle left, R2'}
    for k in ['overbite', 'overjet', 'molar_right', 'molar_left']:
        f = field[k]
        text += f"| {labels[k]} | {f['first_report']['accuracy']:.3f} | {f['first_report']['balanced_accuracy']:.3f} | {f['x7_first_report']['balanced_accuracy']:.3f} | {f['multi_report_discordance']:.1%} |\n"
    s = r5['scores']
    text += f"| Cross bite, corrected reference R5 | {s['corrected_label_model']['accuracy']:.3f} | {s['corrected_label_model']['balanced_accuracy']:.3f} | {s['frozen_X7_model']['balanced_accuracy']:.3f} | {new['discordance']:.1%} |\n"
    text += f"\nR2 : s full-bite - gate misses: macro balanced hit 0,568 against frozen 0,65 . R1 contact / gap without opposition gives 0,450 . The reports have field-wise coverage 0,898 and mean 1,78 size in R2 ; this is no simultaneous guarantee for the entire bite . X7 is a comparison of answers, no algorithm. The simple dental reverse order rule is found {t['named_tooth_recall']:.1%} of named positive tooth observations but has only {t['absence_specificity']:.1%} specificity of the original explicit absence group: FAIL . Unlisted teeth in positive reports is not established negative .\n\nWhere the disagreement arises: after negation correction, 35 / 304 ( 11,5%) remains textual conflicts throughout the crossbite cohort with several readable reports. De121 corrected labels are reading errors, not different clinical perceptions. The Five of 125 literally describes the anterior occurrence; a global label deletes this difference. R6 retains anterior/lateral/unspecified region and rejects the wrong polarity within the right region. The final syntax binding uses the closest previous modifier, so \n\nGeometry association with real report conflict: for overbited, the training geometry model's uncertainty-AUC0,781 (described patient bootstrap 95% 0,642 – 0,904 ), for overjet 0,685 ( 0,544 – 0,818 ). Association gate PASS for these two fields; M1 and original crossbite miss. This shows where geometrically ambiguous model predictions more often coincide with text conflict, **not what causes clinic disunity**. The remaining conflicts of cross-beasts are not causally explained. Example and regional point candidates: raw/DISAGREEMENT_EXAMPLES.json and raw/MIXED_SCOPE_GEOMETRY_R6.json.\n\nWhat does not holds : **877 / 993** source poses have projected gap< − 0,03 mm. Negative projection does not prove physical 3D penetration; it must not be made to contact force or physical contact area. Anatomic FDI , cusp/groove, arc shafts, scan recording and mm accuracy are unvalidated on Bite2Text . The area is a projection; ± 0,05 mm pose- and ± 0,5 mm point errors are declared scenarios, not measured scannero safety. A contact graph alone lacks M1's proximity edge on 112/382 described pages and central incisiveness on 90/193 overjetfall. Opposition resolves the information loss but does not validate the points.\n\nAll gatesQ is preserved: R1 FAIL (category + too small 100 mm² injection in a large map case), R2 FAIL (category), R3 FAIL (range width), R4 PASS (12-fall mathematics), R5 FAIL (global negative control on five correct mixed region findings), R6 PASS (region control). The larger area injection is rejected against the same unchanged tolerance, in separate PREREG_CHECK_AREA_CONTROL. No negative gate has been readjusted.\n\nX7:s 593 / 198 / 198 patient sharing is reused. The test cohort has already been evaluated in X7/X11 and in previous X21 rounds; this is a frozen descriptive re-evaluation, not an untouched external validation cohort. Report Author ID is missing. Parse review of 12 sources is made by the producer. Status **PENDING_INDEPENDENT_REVIEW**.\n\nNext crucial design: independent blinded FDI -/point marking of the frozen 12 cases, then a loaded registered bite and contact image with calibrated observation teams. Current points and source hash are frozen in FROZEN_MEASUREMENT_PANEL.json ; rejects the comparison reader injected 1 mm deviation. The measurements are NOT_RUN . MATCHED_MEASUREMENT_SPEC.md anger kontraktet. If the next consumer only needs tighter mesh geometry, R4 : s content refinement can be extended to the remaining 981 case; this does not add physical information.\n\nResources: map calculation {cost['geometry_preparation_and_query_wall_s']:.1f}s, breda intyg {cost['certificates']['total_wall_s']:.1f}s, exact 12 case refinement {cost['exact_refinement_R4']['wall_s']:.1f}s including independent control . Fit/query, verification and repeat packages are available separately in results.json and raw/RUN_LEDGER.jsonl. Full discovery/code cost and external lab cost UNKNOWN; no 10 x- or cost superior unit is claimed. Max measured model- RSS568,5MiB , ≤ 4 threads, no GPU. Datadisk {r['large_arrays']['total_bytes'] / 1000000.0:.1f}MB , SHA256 in raw/DATA_ARTIFACT_MANIFEST.json ; lane boundary 3 GB. No complete ZIP is unpacked.\n\nLicense: Bite2Text ZIP lacks README / LICENSE and the authors' public page specifies no explicit data license; exact terms **UNKNOWN**. Only private local research and no raw data published. The reused X11 model is trained on Teeth3DS; [official challenge-repot](https://github.com/abenhamadou/3DTeethSeg_MICCAI_Challenges#license) indicates CC BY-NC-ND4.0 for data, but binding to the local snapshot is unclear. No Teeth3DS -mesher is used/exported in X21. The other datasets are not used. Only deidentified cases- ID , no photos or personal data are exported.\n\nSource graphs and generated native graphs are unchanged. Matching contact report target is missing even at the final lookup; GRAPH_FEEDBACK.json proposes bounded coverage DENT - VAL - BITE2TEXT - TOOTH - CONTACT - REPORT and carrying PENDING_INDEPENDENT_REVIEW . No power target is used to bind another quantity.\n"
    (P / 'README_DEMO.md').write_text(text)
    hand = _release_expand(f"X21 -contact-map — six completed designs, PENDING_INDEPENDENT_REVIEW .\n\n993 maps,38280 per-tooth projected gap enclosures. All complete; @DENTAL_CASE_ID@ explicit empty-source rejection. R4 refines12 cases/440 pairs to maxwidth0.004998232mm; rest retain R3 broad bounds. R1/R2 whole-bite report BA FAIL; R3 useful-width FAIL; R5 global mixed-region injection FAIL preserved; R4 andR6 scopedPASS. README_DEMO.md/results.json contain exact quantities, external referents, gates and limits. Run ./run_all.sh; last verification28 checksPASS and live full-case minima error0.\n\nObservation correction:121 X7 crossbite negation labels were wrong; source/hash/old label retained. Test conflicts30/72→7/72; all304 readable multi-report cases140→35. Five literal no-lateral reports also mention anterior crossbite. R6 separates anterior/lateral/unspecified;125 scoped negative-injection controlsPASS and22 dual-region reports retained. Original R6 clause-last-modifier implementation counted21; final adjacent-per-mention syntax counts22, both raw versions preserved. No anatomical/physical truth inferred.\n\nMain blocker: target FDI/points/pose/physicalcontact absent;877/993 source poses have negative projected gap beyond0.03mm. Angle requires independently identified cusp/groove. Point-proximity/contactgraph cannot determine noncontact anterior relation. Geometry entropy covaries with overbite/overjet text conflict but does not identify cause. Named crossbite rule fails specificity.\n\nNext executable construction: fill frozen12-case independent point/FDI annotation port, compare_measurement.py against frozen original coordinates, no refit. Then loaded registered bite + measured contact image/observation law. These observations not available locally, NOT_RUN. Alternatively only for numerical mesh consumer, extend R4 exact contender refinement to981 remaining maps; do not claim this adds clinical information. Declaration/missing coverage DENT-VAL-BITE2TEXT-TOOTH-CONTACT-REPORT; no dispatch or receipt because matching target absent. GRAPH_FEEDBACK PENDING.\n\nData {r['large_arrays']['total_bytes']} bytes under @DENTAL_WORK_ROOT@/X21, SHA256 manifest {r['large_arrays']['manifest_sha256']}. ≤4 threads,<1GB measuredRSS, noGPU/subagents/wholeZIPextraction/mail/push/clinicalrecommendation or other lane mutations. No own background process remains. Full costUNKNOWN, inheritedX11 fit not treated free. Commands/failures COMMANDS.md, all original failed gates retained.\n")
    (P / 'HANDOFF.md').write_text(hand)
    write(P / 'raw/CODE_SNAPSHOT.json', dict(files=[dict(path=str(p.relative_to(P)), sha256=sha(p)) for p in sorted((P / 'code').glob('*.py'))]))
    state('ROUND_COMPLETE_PARENT_GOAL_OPEN', '993 maps; R4/R6 scopedPASS; broad clinical and physical certification UNKNOWN', 'Independent target tooth/point and registered loaded contact measurements; numerical extension only if required', own_running_jobs=0, completed_rounds=6, verification='28 checks PASS, live minimum parity0mm', graph_review_state='PENDING_INDEPENDENT_REVIEW')
if __name__ == '__main__':
    run()
